mapper.select:
SELECT id, bucket_start, bucket_sec, variable_name,
       min_value, max_value, avg_value, sample_count
FROM telemetry_value_rollup
WHERE variable_name = #{variableName}
  AND bucket_sec = #{bucketSec}

    AND bucket_start >= #{from}


    AND bucket_start <= #{to}

ORDER BY bucket_start ASC
